import json
with open('/workspace/subject/commands.json') as f:
    d = json.load(f)
for i, c in enumerate(d['commands']):
    res = c['result']
    texts = []
    if isinstance(res, dict):
        t = res.get('content')
        if isinstance(t, list):
            for item in t:
                if isinstance(item, dict):
                    texts.append(item.get('text',''))
                else:
                    texts.append(str(item))
        elif isinstance(t, str):
            texts.append(t)
        texts.append("DETAILS: " + json.dumps(res.get('details',{})) if res.get('details') else "")
    else:
        texts.append(str(res))
    joined = "".join(texts)
    print(f"=====RESULT {i} (isError={c['isError']}) len={len(joined)}=====")
    print(joined[:3000])
    if len(joined) > 3000:
        print(f"...[truncated, total {len(joined)}]")
    print()
